import type { Recipe } from "../types";

type IngredientLine = [name: string, amount: string, note?: string];
type MethodLine = [title: string, detail: string, why: string, tip?: string];
type RecipeInput = Omit<Recipe, "ingredients" | "steps"> & {
  ingredients: IngredientLine[];
  steps: MethodLine[];
};

function reviewed(input: RecipeInput): Recipe {
  return {
    ...input,
    reviewedOn: "2026-10-24",
    notes: ["Oven temperatures are for a fully preheated conventional oven. Use the stated doneness cues as well as the time range.", ...(input.notes ?? [])],
    ingredients: input.ingredients.map(([name, amount, note], index) => ({ id: `${input.id}-ingredient-${index + 1}`, name, amount, ...(note ? { note } : {}) })),
    steps: input.steps.map(([title, detail, why, tip], index) => ({ id: `${input.id}-step-${index + 1}`, title, detail, why, ...(tip ? { tip } : {}) })),
  };
}

